-- Hub › Instalar app (/dashboard/projetos/instalar-app): "?" em cada ação da tela (RD-95).
-- A tela ganhou o botão "Instalar agora" (Chrome/Edge), o aviso de app já instalado, o link de reserva e a versão.
-- ADITIVA: só texto de ajuda novo; ON CONFLICT DO NOTHING (não altera chave existente).
INSERT INTO public.erp_ajuda_campo (chave, grupo, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum, ordem, rota, vertical, status)
SELECT v.chave, v.grupo, v.rotulo, v.o_que, v.para_que, v.exemplo, v.erro, v.ordem, '/dashboard/projetos/instalar-app', 'hub_construcao', 'publicado'
FROM (VALUES
  ('projetos.instalar_app.instalar_agora', 'Instalar', 'Instalar agora neste aparelho', 'Toque e confirme na janela do navegador. O ícone do PS Gestão aparece na tela inicial (ou no menu do computador).', 'Instala sem precisar achar a opção no menu do navegador. Só aparece no Chrome e no Edge, quando o aparelho ainda não tem o app.', 'Celular Android no Chrome: tocar → "Instalar" → pronto.', 'No iPhone o botão não aparece: lá a instalação é pelo Safari, em Compartilhar → Adicionar à Tela de Início.', 10),
  ('projetos.instalar_app.qr', 'Instalar', 'QR do app', 'Aponte a câmera do celular para o código; o celular abre o link do app.', 'Leva o vendedor direto ao Funil de Oportunidades no celular, sem digitar endereço.', 'Câmera do celular → toque no aviso que aparece → abre o PS Gestão.', 'Escanear com o mesmo aparelho em que a tela está aberta não funciona: use outro celular ou o link.', 20),
  ('projetos.instalar_app.whatsapp', 'Instalar', 'Enviar via WhatsApp', 'Toque, escolha o contato e envie. A mensagem já leva o link e os passos do Android e do iPhone.', 'Manda o app para o vendedor que não está perto de você.', 'Enviar para o vendedor da obra de Cascavel.', 'Quem recebe precisa abrir o link no Chrome (Android) ou no Safari (iPhone), não dentro do próprio WhatsApp.', 30),
  ('projetos.instalar_app.copiar_link', 'Instalar', 'Copiar link', 'Toque para copiar o endereço do app e cole onde quiser (e-mail, mensagem, outro navegador).', 'Serve para mandar o app por outro canal além do WhatsApp.', 'Copiar e colar no e-mail do vendedor.', 'Se aparecer só o botão sem a confirmação "Link copiado!", o navegador bloqueou a cópia: selecione o link no rodapé da tela.', 40),
  ('projetos.instalar_app.link', 'Instalar', 'Link do app', 'É o mesmo endereço do QR. Toque nele ou copie à mão quando a câmera não ler o código.', 'Reserva para quando o QR não abre (câmera sem leitor de QR, tela com reflexo).', 'Digitar o endereço no Chrome do celular.', 'Abrir o link pelo navegador de dentro de outro app (Instagram, WhatsApp) não deixa instalar.', 50),
  ('projetos.instalar_app.versao', 'Instalar', 'Versão do app', 'Só informação: o código da versão que está rodando neste aparelho.', 'Ajuda o suporte a saber se o celular está com a versão mais nova quando algo não bate.', 'Versão do app: 3f9c1a2b7d4e', 'Celular com versão diferente do computador: feche e abra o app de novo para atualizar.', 60)
) v(chave, grupo, rotulo, o_que, para_que, exemplo, erro, ordem)
ON CONFLICT (chave) DO NOTHING;
